CREATE COLUMN TABLE "TEST_AP"."ARC8" ("DocNum" INTEGER CS_INT NOT NULL , "LineNum" INTEGER CS_INT NOT NULL , "InvType" NVARCHAR(20), "DocEntry" INTEGER CS_INT, "DocLine" INTEGER CS_INT, "ObjectType" NVARCHAR(20) DEFAULT '24' NOT NULL , "LogInstanc" INTEGER CS_INT DEFAULT 0 NOT NULL , "PaidEntry" INTEGER CS_INT, "PaidLine" INTEGER CS_INT, PRIMARY KEY ("DocNum", "LineNum", "ObjectType", "LogInstanc")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."ARC8" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$InvType$DocEntry$DocLine$','InvType','DocEntry','DocLine'));
ALTER TABLE "TEST_AP"."ARC8" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$PaidEntry$PaidLine$','PaidEntry','PaidLine'));
CREATE INDEX "ARC8_INVOICE" ON "TEST_AP"."ARC8" ( "InvType" ASC, "DocEntry" ASC, "DocLine" ASC );
CREATE INDEX "ARC8_PAYMENT" ON "TEST_AP"."ARC8" ( "PaidEntry" ASC, "PaidLine" ASC )